#include <HBEngine/SceneRender.hpp>
#include <nlohmann/json.hpp>
#include <iostream>
#include <cassert>
template<class F> static void rejects(F f){bool threw=false;try{f();}catch(const std::exception&){threw=true;}assert(threw);}
#include "scene-2d.hpp"
using namespace hb::gpu;
static std::array<int,3> center(const std::vector<unsigned char>& pixels){return {pixels[(16*32+16)*4],pixels[(16*32+16)*4+1],pixels[(16*32+16)*4+2]};}
static void equal(std::uint64_t actual,std::uint64_t expected,const char* message){if(actual!=expected)throw std::runtime_error(message);}
int main(){try{Device gpu;SceneRenderer r(gpu,32,32);SceneFrame frame;frame.eye={0,0,10,1};frame.ambient={0,0,0,1};r.setLights({});auto mesh=r.createMesh({{{-1,-1,.5f}},{{1,-1,.5f}},{{1,1,.5f}},{{-1,1,.5f}}},{0,1,2,0,2,3});SceneMaterial material;material.unlit=true;material.toneMapped=false;material.depthTest=false;material.depthWrite=false;material.color={.1f,.4f,.2f,1};r.begin(frame);
 constexpr unsigned draws=3000;for(unsigned i=0;i<draws;i++){auto world=identity;world[0]=world[5]=.01f;world[12]=float(i%64)/35-.9f;world[13]=float(i/64)/35-.9f;r.draw(mesh,world,identity,material);}
 const auto warm=r.constantBufferStats();equal(warm.probeUploads,3,"probe warm uploads");equal(warm.twoDUploads,3,"2D warm uploads");equal(warm.probeSkips,draws-3,"probe unchanged skips");equal(warm.twoDSkips,draws-3,"2D unchanged skips");if(warm.retainedCPUBytes>3072)throw std::runtime_error("cache CPU budget");
 SceneRenderer::Bindings2D twoD;twoD.settings.channels[0]=0;const auto draw=[&](const std::array<SceneRenderer::ProbeBinding,2>* probes){r.begin(frame);for(unsigned i=0;i<6;i++)r.draw(mesh,identity,identity,material,{},{},0,0,nullptr,{},{},nullptr,nullptr,&twoD,probes);return center(r.readPixels());};const auto plain=draw(nullptr);const auto changed2D=r.constantBufferStats();equal(changed2D.probeUploads,warm.probeUploads,"2D edit changed probe payload");equal(changed2D.twoDUploads-warm.twoDUploads,3,"2D edit did not reach all slots");if(!(plain[1]>plain[2]&&plain[2]>plain[0]))throw std::runtime_error("plain color");
 std::vector<SceneRenderer::Probe> captures;captures.reserve(2);for(unsigned i=0;i<2;i++){captures.push_back(r.createProbe(16));std::array<float,4> color{0,0,0,1};color[i]=1;for(UINT f=0;f<6;f++){r.beginProbe(captures.back(),f,identity,{0,0,.5f,1},color);r.endProbe();}r.filterProbe(captures.back());}
 std::array<SceneRenderer::ProbeBinding,2> bindings{};bindings[0]={&captures[0],ProbeSettings{}};material.unlit=false;material.color={1,1,1,1};material.metalness=1;material.roughness=.3f;const auto red=draw(&bindings);const auto redStats=r.constantBufferStats();equal(redStats.probeUploads-changed2D.probeUploads,3,"changed probe payload did not upload");equal(redStats.twoDUploads,changed2D.twoDUploads,"3D probe dirtied 2D payload");if(!(red[0]>80&&red[1]<3&&red[2]<3))throw std::runtime_error("red capture");bindings[0].resource=&captures[1];const auto green=draw(&bindings);const auto greenStats=r.constantBufferStats();equal(greenStats.probeUploads,redStats.probeUploads,"SRV-only change uploaded identical constants");if(!(green[1]>80&&green[0]<3&&green[2]<3))throw std::runtime_error("SRV change kept stale image");bindings[0].settings.center[3]=.25f;const auto dim=draw(&bindings);const auto dimStats=r.constantBufferStats();equal(dimStats.probeUploads-greenStats.probeUploads,3,"intensity change not uploaded");if(!(dim[1]<green[1]-20&&dim[1]>20))throw std::runtime_error("intensity stale");material.unlit=true;material.color={.1f,.4f,.2f,1};const auto restored=draw(nullptr);const auto last=r.constantBufferStats();equal(last.probeUploads-dimStats.probeUploads,3,"disabled probe settings not restored");equal(last.twoDUploads,changed2D.twoDUploads,"unchanged 2D cache invalidated");for(unsigned i=0;i<3;i++)if(std::abs(plain[i]-restored[i])>1)throw std::runtime_error("probe removal changed plain image");
 const auto twoDProof=scene2DProof(gpu);
 std::cout<<nlohmann::json({{"passed",true},{"twoDRegression",twoDProof},{"warmDraws",draws},{"warmProbeUploads",warm.probeUploads},{"warm2DUploads",warm.twoDUploads},{"warmSkipsEach",draws-3},{"retainedCPUBytes",last.retainedCPUBytes},{"totalProbeUploads",last.probeUploads},{"total2DUploads",last.twoDUploads},{"srvOnlyChangePreserved",true},{"dirty2DAndProbeSlotsUpdated",true},{"red",red},{"green",green},{"dim",dim},{"restored",restored},{"scope","Actual D3D11 same constants across3000 differing world transforms require3 uploads per group; changed 2D/probe bytes reach each ring slot; SRV-only red/green switch remains visible with zero additional probe uploads; dim/removal restore. CPU cache<=2KiB, no new GPU buffers. No whole-game FPS claim."}}).dump();
}catch(const std::exception& error){std::cerr<<error.what();return 1;}}
